; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcmin (Amstrad CPC - minimal firmware (own screen and keys, firmware for discs and ROMs)), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; main.bas 17: Print "Lists on "; System.Platform
			dw kw_printzoscii
			dw glyph_4C, glyph_69, glyph_73, glyph_74, glyph_73, glyph_20, glyph_6F, glyph_6E
			dw glyph_20, glyph_43, glyph_50, glyph_43, glyph_20, glyph_6D, glyph_69, glyph_6E
			dw glyph_69, glyph_6D, glyph_61, glyph_6C, glyph_20, glyph_66, glyph_69, glyph_72
			dw glyph_6D, glyph_77, glyph_61, glyph_72, glyph_65, 1, 0		; "Lists on CPC minimal firmware\n"

			; main.bas 18: h = List.Create(4)
			dw fn_list_create, lit_4, var_h

			; main.bas 19: seed = 12345
			dw kw_ltov, 12345, var_seed

			; main.bas 20: For i = 1 To 500
			dw kw_ltov, 1, var_i
for1_t:

			; main.bas 21: n = List.Append(h)
			dw fn_list_append, var_h, var_n

			; main.bas 22: If n = 0 Then Print "No room after"; i - 1 : Exit For
			dw kw_l_cpeq, var_n, llit_0
			dw kw_goto_iffalse_n, if2_1
			dw kw_addl, var_i, -1, tmp0
			dw kw_printzoscii
			dw glyph_4E, glyph_6F, glyph_20, glyph_72, glyph_6F, glyph_6F, glyph_6D, glyph_20
			dw glyph_61, glyph_66, glyph_74, glyph_65, glyph_72, 0		; "No room after"
			dw kw_printint, tmp0
			dw kw_printnl
			dw for1_e_go
if2_1:

			; main.bas 23: seed = (seed * 75 + 74) And &H7FFF       ' a small random number generator
			dw kw_mulvl, var_seed, 75, tmp0
			dw kw_addl, tmp0, 74, tmp0
			dw kw_andvl, tmp0, 32767, var_seed

			; main.bas 24: List.SetWord n, ID, i
			dw fn_list_setword, var_n, lit_0, var_i

			; main.bas 25: List.SetWord n, SCORE, seed Mod 10000
			dw kw_modvl, var_seed, 10000, tmp2
			dw fn_list_setword, var_n, lit_2, tmp2

			; main.bas 26: Next
			dw kw_next1l_n, var_i, 500, for1_t
for1_e:

			; main.bas 27: Print List.Count(h); " players"
			dw fn_list_count, var_h, var_list_count_count
			dw kw_printint, var_list_count_count
			dw kw_printzoscii
			dw glyph_20, glyph_70, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72, glyph_73
			dw 1, 0		; " players\n"

			; main.bas 29: r = List.Sort(h, SCORE)
			dw fn_list_sort, var_h, lit_2, var_r

			; main.bas 30: Print "Top 5:"
			dw kw_printzoscii
			dw glyph_54, glyph_6F, glyph_70, glyph_20, glyph_35, glyph_3A, 1, 0		; "Top 5:\n"

			; main.bas 31: n = List.Last(h)
			dw fn_list_last, var_h, var_n

			; main.bas 32: For i = 1 To 5
			dw kw_ltov, 1, var_i
for3_t:

			; main.bas 33: Print "  player "; List.GetWord(n, ID); ": "; List.GetWord(n, SCORE)
			dw fn_list_getword, var_n, lit_0, var_list_getword_getword
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_70, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72
			dw glyph_20, 0		; "  player "
			dw kw_printint, var_list_getword_getword
			dw fn_list_getword, var_n, lit_2, var_list_getword_getword
			dw kw_printzoscii
			dw glyph_3A, glyph_20, 0		; ": "
			dw kw_printint, var_list_getword_getword
			dw kw_printnl

			; main.bas 34: n = List.PrevOf(n)
			dw fn_list_prevof, var_n, var_list_prevof_prevof
			dw kw_l_mov, var_list_prevof_prevof, var_n

			; main.bas 35: Next
			dw kw_next1l_n, var_i, 5, for3_t
for3_e:

			; main.bas 38: n = List.First(h)
			dw fn_list_first, var_h, var_n

			; main.bas 39: Do While n <> 0
do4_t:
			dw kw_l_cpne, var_n, llit_0
			dw kw_goto_iffalse_n, do4_e

			; main.bas 40: nxt = List.NextOf(n)
			dw fn_list_nextof, var_n, var_nxt

			; main.bas 41: If List.GetWord(n, SCORE) < 5000 Then r = List.Delete(h, n)
			dw fn_list_getword, var_n, lit_2, var_list_getword_getword
			dw kw_vtov, var_list_getword_getword, tmp0
			dw kw_scpltvl, tmp0, 5000
			dw kw_goto_iffalse_n, if5_1
			dw fn_list_delete, var_h, var_n, var_r
if5_1:

			; main.bas 42: n = nxt
			dw kw_l_mov, var_nxt, var_n

			; main.bas 43: Loop
			dw do4_t_go
do4_e:

			; main.bas 44: Print List.Count(h); " players with 5000 or more"
			dw fn_list_count, var_h, var_list_count_count
			dw kw_printint, var_list_count_count
			dw kw_printzoscii
			dw glyph_20, glyph_70, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72, glyph_73
			dw glyph_20, glyph_77, glyph_69, glyph_74, glyph_68, glyph_20, glyph_35, glyph_30
			dw glyph_30, glyph_30, glyph_20, glyph_6F, glyph_72, glyph_20, glyph_6D, glyph_6F
			dw glyph_72, glyph_65, 1, 0		; " players with 5000 or more\n"

			; main.bas 45: n = List.Search(h, ID, 250)
			dw fn_list_search, var_h, lit_0, lit_250, var_n

			; main.bas 46: If n <> 0 Then Print "Player 250 scored "; List.GetWord(n, SCORE) Else Print "Player 250 is gone"
			dw kw_l_cpne, var_n, llit_0
			dw kw_goto_iffalse_n, if6_1
			dw fn_list_getword, var_n, lit_2, var_list_getword_getword
			dw kw_printzoscii
			dw glyph_50, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72, glyph_20, glyph_32
			dw glyph_35, glyph_30, glyph_20, glyph_73, glyph_63, glyph_6F, glyph_72, glyph_65
			dw glyph_64, glyph_20, 0		; "Player 250 scored "
			dw kw_printint, var_list_getword_getword
			dw kw_printnl
			dw if6_e_go
if6_1:
			dw kw_printzoscii
			dw glyph_50, glyph_6C, glyph_61, glyph_79, glyph_65, glyph_72, glyph_20, glyph_32
			dw glyph_35, glyph_30, glyph_20, glyph_69, glyph_73, glyph_20, glyph_67, glyph_6F
			dw glyph_6E, glyph_65, 1, 0		; "Player 250 is gone\n"
if6_e:

			; main.bas 47: r = List.Destroy(h)
			dw fn_list_destroy, var_h, var_r

			; main.bas 49: Print "Press a key";
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, 0		; "Press a key"

			; main.bas 50: Do While Inkey <> 0 : Loop
do7_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do7_e
			dw do7_t_go
do7_e:

			; main.bas 51: Do : Frame : Loop Until Inkey <> 0
do8_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do8_t
do8_e:

			; main.bas 52: Print
			dw kw_printnl

			; main.bas 53: End
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

for1_e_go:			ld sp, for1_e
			jp ntc_xn
do4_t_go:			ld sp, do4_t
			jp ntc_xn
if6_e_go:			ld sp, if6_e
			jp ntc_xn
do7_t_go:			ld sp, do7_t
			jp ntc_xn

